import sys, time, importlib.util, numpy as np
sys.path.insert(0, "polus/tools/terrain")
def load(name, path):
    s = importlib.util.spec_from_file_location(name, path); m = importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
P = "polus/"
mods = {"base": load("hb", P + ".orchestra/tasks/62/feel2/argon/hydro_base.py"),
        "head": load("hh", P + ".orchestra/tasks/62/feel2/argon/verify/head_mod/hydrology.py"),
        "merged": load("hm", P + "tools/terrain/hydrology.py")}
region = sys.argv[1]
h, meta, _ = mods["merged"].load_region(P + "data/terrain/" + region, 1024)
cx = meta["world_width_m"] / h.shape[1]; cz = meta["world_height_m"] / h.shape[0]
def cpu(f, *a):
    t = time.process_time(); r = f(*a); return r, time.process_time() - t
res = {}
for k, m in mods.items():
    res[k] = {}
    (filled, parent), t = cpu(m.priority_flood, h); res[k]["pf"] = (filled, parent, t)
for k in mods: print(k, "priority_flood cpu %.2fs" % res[k]["pf"][2], flush=True)
for k in ("head", "merged"):
    assert np.array_equal(res[k]["pf"][0], res["base"]["pf"][0]) and np.array_equal(res[k]["pf"][1], res["base"]["pf"][1]), k
print("priority_flood outputs identical base/head/merged: True")
# routing
filled, parent = res["base"]["pf"][:2]
recv = {}
for k, m in mods.items():
    r, t = cpu(m.flow_receivers, filled, parent, cx, cz); recv[k] = r; print(k, "flow_receivers cpu %.2fs" % t, flush=True)
print("flow_receivers identical:", all(np.array_equal(recv[k], recv["base"]) for k in mods))
acc = {}
for k, m in mods.items():
    (a, o), t = cpu(m.flow_accumulation, recv["base"]); acc[k] = (a, o); print(k, "flow_accumulation cpu %.2fs" % t, flush=True)
print("accumulation identical:", all(np.array_equal(acc[k][0], acc["base"][0]) for k in mods), "order identical:", all(np.array_equal(acc[k][1], acc["base"][1]) for k in mods))
# _select_lakes on the fill depth of a full generate (merged), common input
r = mods["merged"].generate(h, meta["world_width_m"], meta["world_height_m"])
fd = r["fill_depth"]; relief = float(np.ptp(r["original"]))
args = (fd, relief, 4e-5, 1.0, 5e-7, 1.0, 0.0, 1.0, 0.09, cx * cz)
sel = {}
for k, m in mods.items():
    (s, st), t = cpu(m._select_lakes, *args); sel[k] = s; print(k, "_select_lakes cpu %.3fs selected=%d" % (t, s.sum()), flush=True)
print("select_lakes identical:", all(np.array_equal(sel[k], sel["base"]) for k in mods))
# concave profile equality via full generate pre-thalweg is not exposed; compare generate outputs head vs merged
rh = mods["head"].generate(h, meta["world_width_m"], meta["world_height_m"])
for key in ("terrain", "water_height", "river_mask", "fill_depth", "accumulation", "receiver", "flow_speed"):
    a, b = rh[key​], r[key​]
    d = np.abs(a.astype(np.float64) - b.astype(np.float64))
    print("generate head vs merged %-13s changed cells=%d max|d|=%.3f" % (key, int((d > 0).sum()), float(d.max())))
EOF
